"""Exercise the wrappers generated by Home Manager, with only Yazi replaced."""

import os
from pathlib import Path
import re
import subprocess
import sys
import tempfile


def check(source):
    text = Path(source).read_text()
    match = re.search(r"(?ms)^function yy$.*^end$", text)
    assert match, "yy wrapper missing from generated configuration"
    with tempfile.TemporaryDirectory(prefix="yazi integration ") as directory:
        root = Path(directory)
        wrapper = root / "wrapper"
        wrapper.write_text(match.group() + "\n")
        bin_dir = root / "bin"
        bin_dir.mkdir()
        stub = bin_dir / "yazi"
        stub.write_text(f'#!{sys.executable}\n' + '''import os
from pathlib import Path
import sys
args = sys.argv[1:]
assert args[:1] == ["start with spaces"], args
args = args[1:]
if len(args) == 1 and args[0].startswith("--cwd-file="):
    cwd_file = args[0].split("=", 1)[1]
else:
    assert len(args) == 2 and args[0] == "--cwd-file", args
    cwd_file = args[1]
Path(cwd_file).write_text(os.environ["YAZI_TEST_DESTINATION"])
''')
        stub.chmod(0o755)
        temp_dir = root / "temporary files"
        temp_dir.mkdir()
        destination = root / "selected directory with spaces"
        destination.mkdir()
        for selected in (str(destination), str(root), ""):
            env = dict(os.environ, PATH=f"{bin_dir}:{os.environ['PATH']}",
                       TMPDIR=str(temp_dir), YAZI_TEST_DESTINATION=selected)
            command = ["fish", "--no-config", "-c",
                       'source $argv[1]; yy "start with spaces"; printf "%s\\n" $PWD',
                       str(wrapper)]
            result = subprocess.run(command, cwd=root, env=env, text=True,
                                    capture_output=True, check=True)
            assert not result.stderr, result.stderr
            assert result.stdout.strip() == (selected or str(root)), result.stdout
            assert not list(temp_dir.iterdir()), "cwd temporary file leaked"
        print("fish: directory changes, spaces, arguments, unchanged/empty cwd, cleanup passed")


if __name__ == "__main__":
    check(sys.argv[1])
